-- PLEASE / CAL — STEP 18.8 Payroll verification (read-only)
with checks as (
select 1 n,'payroll_parameter_table' check_name,case when to_regclass('public.accounting_payroll_parameters') is not null then 'PASS' else 'FAIL' end status,'Versioned CRA payroll parameter table exists' detail
union all select 2,'payroll_core_tables',case when to_regclass('public.accounting_payroll_employees') is not null and to_regclass('public.accounting_payroll_runs') is not null and to_regclass('public.accounting_payroll_run_lines') is not null then 'PASS' else 'FAIL' end,'Employee, pay-run and run-line tables exist'
union all select 3,'remittance_t4_tables',case when to_regclass('public.accounting_payroll_remittances') is not null and to_regclass('public.accounting_payroll_t4_working_papers') is not null then 'PASS' else 'FAIL' end,'Source-deduction remittance and T4 working-paper tables exist'
union all select 4,'payroll_control_accounts',case when (select count(*) from public.accounting_accounts where code in ('2030','2040','2050','2060','2070','7000','7010','7020') and active=true)=8 then 'PASS' else 'FAIL' end,'Payroll liability and expense control accounts are active'
union all select 5,'cra_2026_parameter_versions',case when (select count(*) from public.accounting_payroll_parameters where province='AB' and tax_year=2026 and engine_version in ('CRA-T4127-122-2026-01','CRA-T4127-123-2026-07'))=2 then 'PASS' else 'FAIL' end,'January and July 2026 CRA parameter versions are installed'
union all select 6,'cra_2026_cpp_rates',case when exists(select 1 from public.accounting_payroll_parameters where province='AB' and effective_from='2026-07-01' and cpp_rate=0.0595 and cpp_base_rate=0.0495 and cpp_first_additional_rate=0.0100 and cpp2_rate=0.0400 and ympe=74600 and yampe=85000 and cpp_max_contribution=4230.45 and cpp2_max_contribution=416.00) then 'PASS' else 'FAIL' end,'2026 CPP/CPP2 reference parameters match seeded values'
union all select 7,'cra_2026_ei_rates',case when exists(select 1 from public.accounting_payroll_parameters where province='AB' and effective_from='2026-07-01' and ei_rate=0.0163 and ei_employer_rate=0.02282 and ei_max_insurable=68900 and ei_max_employee=1123.07 and ei_max_employer=1572.30) then 'PASS' else 'FAIL' end,'2026 EI reference parameters match seeded values'
union all select 8,'cra_2026_td1_defaults',case when exists(select 1 from public.accounting_payroll_parameters where province='AB' and effective_from='2026-07-01' and federal_default_td1=16452 and alberta_default_td1=22769 and federal_cea=1501) then 'PASS' else 'FAIL' end,'2026 default TD1 and Canada Employment Amount references are installed'
union all select 9,'alberta_brackets',case when exists(select 1 from public.accounting_payroll_parameters where province='AB' and effective_from='2026-07-01' and jsonb_array_length(alberta_brackets)=6 and alberta_lowest_rate=0.08) then 'PASS' else 'FAIL' end,'2026 Alberta brackets are versioned'
union all select 10,'federal_brackets',case when exists(select 1 from public.accounting_payroll_parameters where province='AB' and effective_from='2026-07-01' and jsonb_array_length(federal_brackets)=5 and federal_lowest_rate=0.14) then 'PASS' else 'FAIL' end,'2026 federal brackets are versioned'
union all select 11,'employee_role_guard',case when exists(select 1 from pg_trigger where tgname='trg_accounting_payroll_employee_role_guard' and not tgisinternal) then 'PASS' else 'FAIL' end,'Payroll profile requires an active EMPLOYEE business role'
union all select 12,'sin_minimization',case when exists(select 1 from information_schema.columns where table_schema='public' and table_name='accounting_payroll_employees' and column_name='sin_last4') and not exists(select 1 from information_schema.columns where table_schema='public' and table_name='accounting_payroll_employees' and column_name in ('sin','social_insurance_number','full_sin')) then 'PASS' else 'FAIL' end,'CAL stores SIN last four/reference rather than a full SIN field'
union all select 13,'active_run_period_uniqueness',case when exists(select 1 from pg_indexes where schemaname='public' and indexname='accounting_payroll_run_period_active_uq') then 'PASS' else 'FAIL' end,'Non-void pay runs cannot duplicate the same frequency/period'
union all select 14,'posted_line_immutability',case when exists(select 1 from pg_trigger where tgname='trg_accounting_payroll_line_guard' and not tgisinternal) then 'PASS' else 'FAIL' end,'Posted/paid payroll lines are immutable'
union all select 15,'posted_run_guard',case when exists(select 1 from pg_trigger where tgname='trg_accounting_payroll_run_closed_guard' and not tgisinternal) then 'PASS' else 'FAIL' end,'Posted/paid payroll financial fields are protected'
union all select 16,'post_payroll_rpc',case when to_regprocedure('public.accounting_post_payroll_run(uuid,text)') is not null then 'PASS' else 'FAIL' end,'Approved payroll posting RPC exists'
union all select 17,'pay_payroll_rpc',case when to_regprocedure('public.accounting_pay_payroll_run(uuid,uuid,date,text,text)') is not null then 'PASS' else 'FAIL' end,'Payroll payment RPC exists'
union all select 18,'remittance_rpc',case when to_regprocedure('public.accounting_record_payroll_remittance(date,date,uuid,numeric,numeric,numeric,numeric,numeric,numeric,numeric,text,text)') is not null then 'PASS' else 'FAIL' end,'Source-deduction remittance RPC exists'
union all select 19,'t4_rpcs',case when to_regprocedure('public.accounting_generate_t4_working_papers(integer,text)') is not null and to_regprocedure('public.accounting_save_t4_working_paper_review(uuid,text,boolean,text)') is not null then 'PASS' else 'FAIL' end,'T4 working-paper generate/review RPCs exist'
union all select 20,'payroll_posting_rules',case when (select count(*) from public.accounting_posting_rules where source_system='PLEASE' and event_type in ('PAYROLL_POSTED','PAYROLL_PAID','PAYROLL_REMITTANCE_PAID') and enabled=true)=3 then 'PASS' else 'FAIL' end,'STEP 17 payroll posting rules are enabled'
union all select 21,'payroll_rls',case when (select count(*) from pg_class where oid in ('public.accounting_payroll_parameters'::regclass,'public.accounting_payroll_settings'::regclass,'public.accounting_payroll_employees'::regclass,'public.accounting_payroll_runs'::regclass,'public.accounting_payroll_run_lines'::regclass,'public.accounting_payroll_remittances'::regclass,'public.accounting_payroll_t4_working_papers'::regclass) and relrowsecurity)=7 then 'PASS' else 'FAIL' end,'All payroll tables are protected by RLS'
union all select 22,'payroll_sequence_service_role',case when has_sequence_privilege('service_role','public.accounting_payroll_employee_number_seq','USAGE') and has_sequence_privilege('service_role','public.accounting_payroll_run_number_seq','USAGE') and has_sequence_privilege('service_role','public.accounting_payroll_remittance_number_seq','USAGE') then 'PASS' else 'FAIL' end,'Service role can generate employee/run/remittance numbers'
union all select 23,'payroll_audit_triggers',case when (select count(*) from pg_trigger where tgname in ('trg_accounting_payroll_employees_payroll_audit','trg_accounting_payroll_runs_payroll_audit','trg_accounting_payroll_run_lines_payroll_audit','trg_accounting_payroll_remittances_payroll_audit','trg_accounting_payroll_t4_working_papers_payroll_audit') and not tgisinternal)=5 then 'PASS' else 'FAIL' end,'Payroll core evidence is covered by database audit triggers'
union all select 24,'run_totals_nonnegative',case when not exists(select 1 from public.accounting_payroll_runs where gross_pay<0 or net_pay<0 or employee_cpp<0 or employee_cpp2<0 or employee_ei<0 or income_tax<0 or employer_cpp<0 or employer_cpp2<0 or employer_ei<0) then 'PASS' else 'FAIL' end,'No invalid negative statutory payroll totals exist'
union all select 25,'no_posted_run_without_lines',case when not exists(select 1 from public.accounting_payroll_runs r where r.status in ('POSTED','PAID') and not exists(select 1 from public.accounting_payroll_run_lines l where l.payroll_run_id=r.id)) then 'PASS' else 'FAIL' end,'Every posted/paid payroll run has employee lines'
union all select 26,'paid_run_financial_account',case when not exists(select 1 from public.accounting_payroll_runs where status='PAID' and payment_financial_account_id is null) then 'PASS' else 'FAIL' end,'Paid payroll runs retain financial-account evidence'
union all select 27,'t4_unique_employee_year',case when not exists(select tax_year,employee_id from public.accounting_payroll_t4_working_papers group by tax_year,employee_id having count(*)>1) then 'PASS' else 'FAIL' end,'T4 working papers are unique by tax year and employee'
union all select 28,'payroll_parameter_ranges',case when not exists(select 1 from public.accounting_payroll_parameters where effective_to is not null and effective_to<effective_from) then 'PASS' else 'FAIL' end,'Payroll parameter effective-date ranges are valid'
)
select n,check_name,status,detail from checks order by n;
